def greedy(w,K=8):
    C=np.cos(w*t); S=np.sin(w*t)
    F={}
    g={'1':np.ones_like(t),'x':x,'x2':x*x,'x3':x**3,'sx':np.sqrt(x),'1/x':1/x,'tanhx':np.tanh(x),'expmx':np.exp(-x),'lx':np.log(x)}
    h={'1':np.ones_like(v),'v':v,'v2':v*v,'v3':v**3,'1/v':1/v,'1/v2':1/v**2,'sv':np.sqrt(v),'tanhv':np.tanh(v),'expmv':np.exp(-v),'lv':np.log(v),'vabsv':v*np.abs(v)}
    tt={'C':C,'S':S,'1':np.ones_like(t),'1/t':1/t,'t':t,'tC':t*C,'tS':t*S,'Ct':C/t,'St':S/t}
    for a,fa in g.items():
        for b,fb in h.items():
            F[a+'*'+b]=fa*fb
    for a,fa in tt.items():
        for b,fb in h.items():
            F[a+'|'+b]=fa*fb
        for b,fb in g.items():
            F[a+'&'+b]=fa*fb
    names=list(F.keys()); sel=[]
    for k in range(K):
